// Parse thong tin payload thanh 2 value temp/humid
let data = msg.payload;
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch(e) {}
}

let temp = data.temp;
let humid = data.humid;

// Cap nhat status duoi node
node.status({fill: "green", shape: "dot", text: "temp: " + temp + "�C | humid: " + humid + "%"});

// Output 1: Temperature value
let msgTemp = {
    topic: "temperature",
    payload: temp
};

// Output 2: Humidity value
let msgHumid = {
    topic: "humidity",
    payload: humid
};

return [msgTemp, msgHumid];

// OWASP I2: chỉ nhận telemetry có chữ ký HMAC-SHA256 đúng và còn mới.
// Bản tin = JSON gốc S bỏ '}' cuối + ,"sig":"<hex HMAC(S)>"} (giống firmware và web).
const key = env.get('SHELF_HMAC_KEY') || '';
if (key.length < 16) {
    node.status({ fill: 'red', shape: 'ring', text: 'Chưa cấu hình SHELF_HMAC_KEY' });
    node.warn('Bỏ telemetry: chưa cấu hình SHELF_HMAC_KEY (>= 16 ký tự)');
    return null;
}

function reject(reason) {
    const n = (context.get('rejected') || 0) + 1;
    context.set('rejected', n);
    node.status({ fill: 'red', shape: 'dot', text: 'Đã loại ' + n + ': ' + reason });
    node.warn('Loại telemetry: ' + reason);
    return null;
}

const raw = Buffer.isBuffer(msg.payload) ? msg.payload.toString('utf8') : String(msg.payload);
const m = /,"sig":"([0-9a-f]{64})"\}$/.exec(raw);
if (!m) return reject('thiếu chữ ký');

const body = raw.slice(0, m.index) + '}';
const expected = crypto.createHmac('sha256', key).update(body, 'utf8').digest();
const got = Buffer.from(m[1], 'hex');
if (got.length !== expected.length || !crypto.timingSafeEqual(got, expected)) return reject('chữ ký sai');

let data;
try { data = JSON.parse(body); } catch (e) { return reject('JSON hỏng'); }

// Chống phát lại: ts (giây Unix do ESP32 lấy từ NTP) phải mới và không lùi.
const ts = Number(data.ts || 0);
if (!ts || Math.abs(Date.now() / 1000 - ts) > 300) return reject('bản tin cũ hoặc ts sai');
if (ts < (context.get('lastTs') || 0)) return reject('ts lùi (phát lại)');
context.set('lastTs', ts);

msg.payload = data;
msg.verified = true;
node.status({ fill: 'green', shape: 'dot', text: 'Hợp lệ ' + new Date().toLocaleTimeString('vi-VN') });
return msg;

// Firmware publishes canonical IDs K01..K10; detailed widgets exist for K01..K03.
const shelves = (msg.payload && msg.payload.shelves) || [];
const byId = new Map(shelves.map(s => [String(s.id).toUpperCase(), s]));
return ['K01', 'K02', 'K03'].map(id => {
    const shelf = byId.get(id);
    return shelf ? { payload: shelf, topic: msg.topic } : null;
});

// Lưu toàn bộ dữ liệu vào flow context để các node khác truy cập
let data = msg.payload;
flow.set('lastTelemetry', data);
flow.set('lastUpdate', new Date().toLocaleString('vi-VN'));
flow.set('uptime', data.uptime || 0);
flow.set('totalAlerts', data.total_alerts || 0);

// Lưu lịch sử (giữ 100 bản ghi gần nhất)
let history = flow.get('history') || [];
history.push({
    timestamp: Date.now(),
    shelves: data.shelves,
    alerts: data.total_alerts
});
if (history.length > 100) history.shift();
flow.set('history', history);

node.status({fill: 'green', shape: 'dot', text: `Saved @ ${new Date().toLocaleTimeString('vi-VN')}`});
return msg;

// Tính toán thống kê tổng hợp cho 10 Kệ hàng Tạp hóa
let shelves = msg.payload.shelves || [];
let totalQty = 0, totalWeight = 0, alertCount = 0;

for (let s of shelves) {
    totalQty += s.qty;
    totalWeight += s.weight;
    if (s.low_stock) alertCount++;
}

let statusMsg = {
    payload: alertCount > 0 
        ? `⚠️ Có ${alertCount}/10 kệ đang thiếu hàng!` 
        : '✅ Toàn bộ 10 kệ tạp hóa đang đủ hàng',
    topic: 'status'
};

let totalQtyMsg = { payload: totalQty };
let totalWeightMsg = { payload: totalWeight };
let alertMsg = { payload: alertCount };
let uptimeMsg = { payload: msg.payload.uptime || 0 };

return [statusMsg, totalQtyMsg, totalWeightMsg, alertMsg, uptimeMsg];

// Hiển thị số lượng Kệ 1 dạng gauge
let s = msg.payload;
node.status({
    fill: s.low_stock ? 'red' : 'green',
    shape: 'ring',
    text: `${s.name}: ${s.qty} món (${s.weight}g)`
});
msg.payload = s.qty;
msg.topic = 'K1 - ' + s.name;
return msg;

let s = msg.payload;
node.status({
    fill: s.low_stock ? 'red' : 'green',
    shape: 'ring',
    text: `${s.name}: ${s.qty} món (${s.weight}g)`
});
msg.payload = s.qty;
msg.topic = 'K2 - ' + s.name;
return msg;

let s = msg.payload;
node.status({
    fill: s.low_stock ? 'red' : 'green',
    shape: 'ring',
    text: `${s.name}: ${s.qty} món (${s.weight}g)`
});
msg.payload = s.qty;
msg.topic = 'K3 - ' + s.name;
return msg;

let s = msg.payload;
msg.payload = s.weight;
msg.topic = 'K1 - ' + s.name;
return msg;

let s = msg.payload;
msg.payload = s.weight;
msg.topic = 'K2 - ' + s.name;
return msg;

let s = msg.payload;
msg.payload = s.weight;
msg.topic = 'K3 - ' + s.name;
return msg;

let s = msg.payload;
let icon = s.low_stock ? '🔴' : '🟢';
msg.payload = `${icon} ${s.name}: ${s.qty} món | ${s.weight}g | Ngưỡng: ${s.min}`;
node.status({fill: s.low_stock ? 'red' : 'green', shape: 'dot', text: msg.payload});
return msg;

let s = msg.payload;
let icon = s.low_stock ? '🔴' : '🟢';
msg.payload = `${icon} ${s.name}: ${s.qty} món | ${s.weight}g | Ngưỡng: ${s.min}`;
node.status({fill: s.low_stock ? 'red' : 'green', shape: 'dot', text: msg.payload});
return msg;

let s = msg.payload;
let icon = s.low_stock ? '🔴' : '🟢';
msg.payload = `${icon} ${s.name}: ${s.qty} món | ${s.weight}g | Ngưỡng: ${s.min}`;
node.status({fill: s.low_stock ? 'red' : 'green', shape: 'dot', text: msg.payload});
return msg;

let data = flow.get('lastTelemetry');
if (!data || !data.shelves) return null;

let table = '<table border="1" style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:13px">';
table += '<tr style="background:#1e3a8a;color:white;text-align:left;padding:8px"><th>Mã</th><th>Phân loại</th><th>Tên sản phẩm</th><th>Tồn kho</th><th>Tải trọng</th><th>Ngưỡng</th><th>Trạng thái</th></tr>';

for (let s of data.shelves) {
    let color = s.low_stock ? '#fee2e2' : '#f0fdf4';
    let textColor = s.low_stock ? '#b91c1c' : '#15803d';
    let status = s.low_stock ? '⚠️ THIẾU HÀNG' : '✅ ĐỦ HÀNG';
    let cat = s.category || 'Tạp hóa';
    table += `<tr style="background:${color};color:#1f2937">
      <td style="padding:6px"><b>${s.id}</b></td>
      <td style="padding:6px">${cat}</td>
      <td style="padding:6px"><b>${s.name}</b></td>
      <td style="padding:6px;text-align:center"><b>${s.qty}</b> món</td>
      <td style="padding:6px;text-align:right">${s.weight}g</td>
      <td style="padding:6px;text-align:center">${s.min}</td>
      <td style="padding:6px;color:${textColor};font-weight:bold">${status}</td>
    </tr>`;
}
table += '</table>';

msg.payload = table;
node.status({fill: 'blue', shape: 'dot', text: `${data.shelves.length} kệ tạp hóa | Rendered`});
return msg;

let sec = msg.payload;
let h = Math.floor(sec / 3600);
let m = Math.floor((sec % 3600) / 60);
let s = sec % 60;
let text = `${h}h ${m}m ${s}s`;
node.status({fill: 'green', shape: 'dot', text: text});
msg.payload = text;
return msg;

// Kiểm tra ngưỡng tồn kho cho cả 10 Kệ hàng & Chống spam Telegram
let lastAlerts = context.get('lastAlerts') || {};
let now = Date.now();
let interval = 5 * 60 * 1000; // Nhắc lại sau mỗi 5 phút nếu chưa tiếp hàng

let shelves = msg.payload.shelves || [];
let alertMessages = [];
let alertShelves = [];
let restockedShelves = [];

for (let shelf of shelves) {
    if (shelf.low_stock) {
        let lastTime = lastAlerts[shelf.id] || 0;
        if (now - lastTime >= interval) {
            alertMessages.push(`⚠️ *KỆ [${shelf.id}] - ${shelf.name}*: Còn *${shelf.qty}* món (Tải trọng: ${shelf.weight}g, Ngưỡng min: ${shelf.min})`);
            alertShelves.push(shelf);
            lastAlerts[shelf.id] = now;
        }
    } else if (lastAlerts[shelf.id]) {
        // Kệ đã từng bị cảnh báo nay đủ hàng trở lại: báo "đã bổ sung hàng" một lần.
        restockedShelves.push(shelf);
        delete lastAlerts[shelf.id];
    }
}

context.set('lastAlerts', lastAlerts);

if (alertMessages.length > 0 || restockedShelves.length > 0) {
    msg.alertMessages = alertMessages;
    msg.alertShelves = alertShelves;
    msg.alertCount = alertMessages.length;
    msg.restockedShelves = restockedShelves;
    node.status(alertMessages.length > 0
        ? {fill: 'red', shape: 'dot', text: `${alertMessages.length}/10 kệ cần cảnh báo!`}
        : {fill: 'green', shape: 'dot', text: `${restockedShelves.length} kệ đã bổ sung hàng`});
    return msg;
}

node.status({fill: 'green', shape: 'ring', text: 'OK - 10 kệ đủ hàng'});
return null;

// Format tin nhan MarkdownV2 dep cho Telegram
// Escape cac ky tu dac biet trong MarkdownV2
function escMD(str) {
    return String(str).replace(/([_*\[\]()~`>#+\-=|{}.!\\])/g, '\\$1');
}

let alertShelves = msg.alertShelves || [];
let restocked = msg.restockedShelves || [];
let now = new Date();

// Tinh uptime format
let up = flow.get('uptime') || 0;
let h = Math.floor(up / 3600);
let m = Math.floor((up % 3600) / 60);
let uptimeStr = h + 'h ' + m + 'm';

// Format thoi gian dep
let timeStr = now.toLocaleString('vi-VN', {
    timeZone: 'Asia/Ho_Chi_Minh',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
});

// Phan loai muc do khan cap
let critical = alertShelves.filter(s => s.qty === 0);
let low = alertShelves.filter(s => s.qty > 0);

let lines = [];

// === HEADER ===
const SEP = '\u2501'.repeat(22);
if (alertShelves.length > 0) {
    lines.push('\u{1F6A8} *C\u1EA2NH B\u00C1O KHO H\u00C0NG* \u{1F6A8}');
    lines.push(SEP);
    lines.push('\u{1F3EA} *Ti\u1EC7m T\u1EA1p H\u00F3a Smart* \u2014 Nh\u00F3m 22');
    lines.push('\u{1F4CB} *' + escMD(alertShelves.length) + ' k\u1EC7 h\u00E0ng c\u1EA7n ti\u1EBFp h\u00E0ng ngay\\!*');
} else {
    lines.push('\u2705 *K\u1EC6 H\u00C0NG \u0110\u00C3 \u0110\u01AF\u1EE2C B\u1ED4 SUNG* \u2705');
    lines.push(SEP);
    lines.push('\u{1F3EA} *Ti\u1EC7m T\u1EA1p H\u00F3a Smart* \u2014 Nh\u00F3m 22');
}
lines.push('');

// === KE HET HANG (do) ===
if (critical.length > 0) {
    lines.push('\u{1F534} *H\u1EBET H\u00C0NG \u2014 C\u1EA6N XU\u1EA4T KHO NGAY:*');
    for (let s of critical) {
        lines.push('  \u2022 `' + escMD(s.id) + '` *' + escMD(s.name) + '*');
        lines.push('    \u2192 T\u1ED3n: *0 m\u00F3n* \u2503 KL: `0g` \u2503 Min: ' + escMD(s.min));
    }
    lines.push('');
}

// === KE SAP HET (vang) ===
if (low.length > 0) {
    lines.push('\u{1F7E1} *S\u1EAEP H\u1EBET \u2014 C\u1EA6N B\u1ED4 SUNG:*');
    for (let s of low) {
        let pct = Math.round((s.qty / (s.min * 2)) * 100);
        let bar = '';
        let filled = Math.round(pct / 20);
        for (let i = 0; i < 5; i++) bar += (i < filled ? '\u2588' : '\u2591');
        lines.push('  \u2022 `' + escMD(s.id) + '` *' + escMD(s.name) + '*');
        lines.push('    \u2192 T\u1ED3n: *' + escMD(s.qty) + ' m\u00F3n* \u2503 KL: `' + escMD(s.weight) + 'g` \u2503 \\[' + bar + '\\] ' + pct + '%');
    }
    lines.push('');
}

// === KE DA BO SUNG HANG (xanh) ===
if (restocked.length > 0) {
    lines.push('\u{1F7E2} *\u0110\u00C3 B\u1ED4 SUNG \u2014 \u0110\u1EE6 H\u00C0NG TR\u1EDE L\u1EA0I:*');
    for (let s of restocked) {
        lines.push('  \u2022 `' + escMD(s.id) + '` *' + escMD(s.name) + '*');
        lines.push('    \u2192 T\u1ED3n: *' + escMD(s.qty) + ' m\u00F3n* \u2503 KL: `' + escMD(s.weight) + 'g` \u2503 Min: ' + escMD(s.min));
    }
    lines.push('');
}

// === FOOTER ===
lines.push('\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501');
lines.push('\u{1F550} *Th\u1EDDi gian:* `' + escMD(timeStr) + '`');
lines.push('\u23F1 *Uptime ESP32:* `' + escMD(uptimeStr) + '`');
lines.push('');
lines.push('\u{1F4F2} _H\u1EC7 th\u1ED1ng IoT Smart Shelf \u2014 ESP32 \\+ Node\\-RED_');
if (alertShelves.length > 0) {
    lines.push('\u{1F449} *Vui l\u00F2ng ki\u1EC3m tra k\u1EC7 h\u00E0ng ngay\\!*');
} else {
    lines.push('\u{1F44D} _Kh\u00F4ng c\u1EA7n thao t\u00E1c th\u00EAm\\._');
}

let text = lines.join('\n');

// Danh sach Chat ID nhan canh bao
// Credentials are injected by environment variables; do not store them in this flow.
const token = env.get('TELEGRAM_BOT_TOKEN') || '';
const chatIds = (env.get('TELEGRAM_CHAT_IDS') || '').split(',').map(id => id.trim()).filter(Boolean);
if (!token || chatIds.length === 0) {
    node.status({fill: 'grey', shape: 'ring', text: 'Telegram not configured'});
    return null;
}
const url = 'https://api.telegram.org/bot' + token + '/sendMessage';
const messages = chatIds.map(cid => ({url, payload: {chat_id: cid, text, parse_mode: 'MarkdownV2'}}));
node.status({fill: 'yellow', shape: 'dot', text: 'Sending Telegram alerts: ' + messages.length});
return [messages];

if (msg.payload && msg.payload.ok) {
    node.status({fill: 'green', shape: 'dot', text: `OK - Chat ${msg.payload.result.chat.id} @ ${new Date().toLocaleTimeString('vi-VN')}`});
} else {
    node.status({fill: 'red', shape: 'dot', text: `FAILED: ${JSON.stringify(msg.payload)}`});
}
return null;

// OWASP I2/I3: ký lệnh downlink bằng HMAC-SHA256 kèm ts (ms) và nonce.
// ESP32 từ chối lệnh không có chữ ký đúng, lệnh cũ hơn 120 s và nonce đã dùng.
const key = env.get('SHELF_HMAC_KEY') || '';
if (key.length < 16) {
    node.status({ fill: 'red', shape: 'ring', text: 'Chưa cấu hình SHELF_HMAC_KEY' });
    node.error('Không gửi lệnh: chưa cấu hình SHELF_HMAC_KEY (>= 16 ký tự)', msg);
    return null;
}

let cmd = msg.payload;
if (typeof cmd === 'string') {
    try { cmd = JSON.parse(cmd); } catch (e) { node.error('Lệnh không phải JSON', msg); return null; }
}
if (!cmd || typeof cmd.cmd !== 'string') { node.error('Lệnh thiếu trường cmd', msg); return null; }

const clean = Object.assign({}, cmd);
delete clean.sig;
delete clean.ts;
delete clean.nonce;
const body = JSON.stringify(Object.assign(clean, { ts: Date.now(), nonce: crypto.randomBytes(8).toString('hex') }));
const sig = crypto.createHmac('sha256', key).update(body, 'utf8').digest('hex');

msg.payload = body.slice(0, -1) + ',"sig":"' + sig + '"}';
node.status({ fill: 'green', shape: 'dot', text: 'Đã ký lệnh ' + cmd.cmd });
return msg;

let errorLog = flow.get('errorLog') || [];
errorLog.push({
    time: new Date().toLocaleString('vi-VN'),
    source: msg.error.source.name || 'Unknown',
    message: msg.error.message || 'No message'
});
if (errorLog.length > 50) errorLog.shift();
flow.set('errorLog', errorLog);

node.status({fill: 'red', shape: 'dot', text: `Lỗi: ${msg.error.message}`});
msg.payload = `❌ [ERROR] ${msg.error.source.name}: ${msg.error.message}`;
return msg;

let st = msg.status;
if (st && st.text) {
    if (st.text.includes('connected')) {
        node.status({fill: 'green', shape: 'dot', text: 'MQTT: Connected'});
    } else if (st.text.includes('disconnected')) {
        node.status({fill: 'red', shape: 'ring', text: 'MQTT: Disconnected!'});
    }
}
return null;

// Quản lý trạng thái 10 Kệ hàng Tạp hóa Thông minh (K01 - K10)
let default10 = [
  { id: "K01", name: "Coca-Cola 330ml", weight: 990, unit: 330, qty: 3, min: 3, low_stock: false, category: "Đồ uống" },
  { id: "K02", name: "Mì Hảo Hảo Tôm", weight: 375, unit: 75, qty: 5, min: 5, low_stock: false, category: "Ăn liền" },
  { id: "K03", name: "Bánh Oishi Snack", weight: 200, unit: 50, qty: 4, min: 4, low_stock: false, category: "Bánh kẹo" },
  { id: "K04", name: "Sữa tươi Vinamilk", weight: 760, unit: 190, qty: 4, min: 4, low_stock: false, category: "Sữa tươi" },
  { id: "K05", name: "Bột giặt OMO 800g", weight: 2400, unit: 800, qty: 3, min: 2, low_stock: false, category: "Hóa mỹ phẩm" },
  { id: "K06", name: "Dầu ăn Simply 1L", weight: 3680, unit: 920, qty: 4, min: 3, low_stock: false, category: "Gia vị" },
  { id: "K07", name: "Nước mắm Nam Ngư", weight: 2200, unit: 550, qty: 4, min: 3, low_stock: false, category: "Gia vị" },
  { id: "K08", name: "Bánh Chocopie Hộp", weight: 594, unit: 198, qty: 3, min: 2, low_stock: false, category: "Bánh kẹo" },
  { id: "K09", name: "Trứng gà Ba Huân", weight: 1800, unit: 600, qty: 3, min: 2, low_stock: false, category: "Thực phẩm" },
  { id: "K10", name: "Tương ớt Chinsu", weight: 1120, unit: 280, qty: 4, min: 3, low_stock: false, category: "Gia vị" }
];

let shelves10 = flow.get('shelves10') || default10;

// 1. Nhận dữ liệu thực tế từ ESP32 Wokwi (Phân khu A: K01, K02, K03)
if (msg.payload && Array.isArray(msg.payload.shelves)) {
    for (let s of msg.payload.shelves) {
        let idx = shelves10.findIndex(x => x.id === s.id || (s.id === 'K1' && x.id === 'K01') || (s.id === 'K2' && x.id === 'K02') || (s.id === 'K3' && x.id === 'K03'));
        if (idx !== -1) {
            shelves10[idx].weight = s.weight;
            shelves10[idx].qty = s.qty;
            if (s.unit) shelves10[idx].unit = s.unit;
            if (s.min !== undefined) shelves10[idx].min = s.min;
            shelves10[idx].low_stock = (shelves10[idx].qty <= shelves10[idx].min);
        }
    }
}

// 2. Xử lý lệnh Tare hoặc Set cấu hình cho bất kỳ kệ nào từ Downlink
if (msg.payload && msg.payload.cmd) {
    let target = msg.payload.id || "";
    let idx = shelves10.findIndex(x => x.id === target || (target === 'K1' && x.id === 'K01') || (target === 'K2' && x.id === 'K02') || (target === 'K3' && x.id === 'K03'));
    if (idx !== -1) {
        if (msg.payload.cmd === 'tare') {
            shelves10[idx].weight = 0;
            shelves10[idx].qty = 0;
            shelves10[idx].low_stock = true;
        } else if (msg.payload.cmd === 'set') {
            if (msg.payload.name) shelves10[idx].name = msg.payload.name;
            if (msg.payload.unit) shelves10[idx].unit = msg.payload.unit;
            if (msg.payload.min !== undefined) shelves10[idx].min = msg.payload.min;
            shelves10[idx].qty = Math.round(shelves10[idx].weight / shelves10[idx].unit);
            shelves10[idx].low_stock = (shelves10[idx].qty <= shelves10[idx].min);
        }
    }
}

// 3. Simulation runs only when manually triggered; it does not overwrite telemetry on a timer.
// Mô phỏng khách mua sắm tiệm tạp hóa (K04 - K10)
if (msg.topic === 'simulate_grocery_event') {
    let targetIdx = Math.floor(Math.random() * 7) + 3; // Index 3 đến 9 (K04-K10)
    let s = shelves10[targetIdx];
    let change = Math.random() > 0.35 ? -1 : 2; // Khách mua hoặc bổ sung
    s.qty = Math.max(0, Math.min(10, s.qty + change));
    s.weight = s.qty * s.unit;
    s.low_stock = (s.qty <= s.min);
}

// 4. Tính toán tổng hợp
let alertCount = shelves10.filter(x => x.low_stock).length;
// Lấy uptime thật của ESP32; bản tin mô phỏng không có uptime thì giữ giá trị cũ.
let uptime = (msg.payload && Number.isFinite(msg.payload.uptime)) ? msg.payload.uptime : (flow.get('uptime') || 0);

flow.set('shelves10', shelves10);
flow.set('uptime', uptime);

msg.payload = {
    device: msg.topic === 'simulate_grocery_event' ? 'NodeRED_Grocery_Demo' : (msg.payload.device || 'ESP32_SmartShelf_10Tiers'),
    source: msg.topic === 'simulate_grocery_event' ? 'node-red-demo' : (msg.payload.source || 'sample'),
    store: "TapHoaSmart_Q7",
    uptime: uptime,
    shelves: shelves10,
    total_alerts: alertCount,
    timestamp: new Date().toISOString()
};

flow.set('lastTelemetry', msg.payload);
flow.set('totalAlerts', alertCount);

node.status({
    fill: alertCount > 0 ? 'red' : 'green',
    shape: 'dot',
    text: `10 Kệ: ${alertCount} kệ thiếu hàng | Updated`
});

return msg;
